 const value={provider:results[2]?.[0]||{provider:"binance",status:"unknown"},quotes,summary:{tracked_assets:assets.length,quoted_assets:quotes.length,fresh_quotes:quoteFresh,stale_quotes:Math.max(0,assets.length-quoteFresh),average_change_24h_pct:avg,gainers_count:changes.filter(x=>x>0).length,losers_count:changes.filter(x=>x<0).length,latest_received_at:maxTimestamp(quotes,"received_at"),latest_source_timestamp:maxTimestamp(quotes,"source_timestamp")},candle_freshness:{"5m":{latest_received_at:candle5?.received_at||null,fresh:!!candle5&&now-Date.parse(candle5.received_at)<=600000},"1h":{latest_received_at:candle1?.received_at||null,fresh:!!candle1&&now-Date.parse(candle1.received_at)<=7200000}},read_only:true,financial_operations_enabled:false};
