 if(!assets.length)return json({symbol,interval,candles:[],fresh:false});
 const candles=await tableRows(env,"market_candles",{select:"open_time,close_time,open_price,high_price,low_price,close_price,volume,quote_volume,received_at",asset_id:"eq."+assets[0].id,provider:"eq.binance",interval_code:"eq."+interval,order:"open_time.desc",limit:"60"});
